 const api={get selected(){return selected;},get handles(){return handles;},get witnessFaults(){return witnessFaults;},get heldRender(){return !!heldRender;},get heldAck(){return !!heldAck;},get heldCallbacks(){return callbacks.length;},holdNavigation(f){gateFrame=f;gate=true;},releaseNavigation(){gate=false;for(const cb of callbacks.splice(0))cb();},releaseWork(){heldRender?.resolve();heldAck?.resolve();},async finish(){api.releaseNavigation();api.releaseWork();await overlayUntil(()=>work.size===0,'all forwarded render/dispose promises settle after caller browser close');for(const restore of restores.reverse())restore();const summary={attempts:selected?.calls||0,settled:selected?.settled||0,sameConfig:selected?.sameConfig??null,sameWitness:selected?.sameWitness??null,witnessFaults,handles:handles.length,disposeCalls:handles.reduce((n,h)=>n+h.disposeCalls,0),allHandlesDisposed:handles.every(h=>h.disposed&&h.handle.disposed),eachHandleDisposedOnce:handles.every(h=>h.disposeCalls===1),unresolved:work.size,heldCallbacks:callbacks.length,deliveredCallbacks,failureWitnesses,firstForwarded:selected?.firstForwarded||false,secondForwarded:selected?.secondForwarded||false,browserConnected:browser.connected};console.log('OVERLAY-CLEANUP '+JSON.stringify(summary));assert.equal(summary.unresolved,0);assert.equal(summary.heldCallbacks,0);assert.equal(summary.allHandlesDisposed,true);assert.equal(summary.eachHandleDisposedOnce,true);assert.equal(summary.browserConnected,false);return summary;}};return api;
